    with self._lock:
        existing = self._find_did_by_handle_locked(handle, tenant)
        if existing is not None:
            # 幂等重试：每次成功都记审计
            self._append_audit_locked(
                tenant, "did.created", "did", existing.did
            )
            self._save_locked()
            return existing

        if private_pem is not None:
